-- ===== U9 vocab 覆盖灌库(volume='9',41词)。分步跑。=====

SELECT 'U9 灌前' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U9';

DELETE FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U9';
SELECT 'U9 DELETE后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U9';  -- 应0


SELECT 'U9 INSERT后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U9';  -- 应41
SELECT word, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U9' GROUP BY word HAVING count(*)>1;  -- 查重应0行